WITH daily_market_sales AS ( SELECT d.d_year, d.d_month_seq, d.d_date, s.s_market_id, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(ss.ss_ext_discount_amt) AS total_discount, CASE WHEN d.d_holiday = 'Y' THEN 'Holiday' ELSE 'Regular' END AS day_type FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk GROUP BY d.d_year, d.d_month_seq, d.d_date, s.s_market_id, d.d_holiday ), ranked_days AS ( SELECT d_year, d_month_seq, d_date, s_market_id, total_sales, total_discount, day_type, ROW_NUMBER() OVER (PARTITION BY d_year, d_month_seq, s_market_id ORDER BY total_sales DESC) AS day_rank, total_discount / NULLIF(total_sales, 0) AS discount_ratio FROM daily_market_sales ) SELECT d_year, d_month_seq, d_date, s_market_id, total_sales, day_type, discount_ratio, day_rank FROM ranked_days WHERE day_rank <= 5 ORDER BY d_year DESC, d_month_seq, s_market_id, day_rank
